35:   HANDLE hFile = CreateFile(filePath.c_str(), GENERIC_READ, 0, NULL,
36:                             OPEN_EXISTING, FILE_ATTRIBUTE_NORMAL, NULL);
37:   if (hFile == INVALID_HANDLE_VALUE) {
38:     throw(std::runtime_error("Error opening file " + filePath + "."));
